 1→import { test, expect } from '@playwright/test';
 2→
 3→test.describe('Navigation between Home and Learn', () => {
 4→  test('should show header with navigation links on both pages and navigate between them', async ({ page }) => {
 5→    // Start on the homepage
 6→    await page.goto('/');
 7→
 8→    // Header should be visible on the homepage
 9→    const header = page.getByTestId('app-header');
10→    await expect(header).toBeVisible();
11→
12→    // Header should contain navigation links to Home and Learn
13→    const homeLink = header.getByTestId('nav-home');
14→    const learnLink = header.getByTestId('nav-learn');
15→    await expect(homeLink).toBeVisible();
16→    await expect(learnLink).toBeVisible();
17→
18→    // Navigate to the learn page by clicking the Learn link
19→    await learnLink.click();
20→    await expect(page).toHaveURL('/learn');
21→
22→    // Header should still be visible on the learn page
23→    await expect(header).toBeVisible();
24→    await expect(homeLink).toBeVisible();
25→    await expect(learnLink).toBeVisible();
26→
27→    // Navigate back to the homepage by clicking the Home link
28→    await homeLink.click();
29→    await expect(page).toHaveURL('/');
30→
31→    // Header should still be visible after navigating back
32→    await expect(header).toBeVisible();
33→  });
34→});
