import { TestBed } from '@angular/core/testing';
import { provideRouter, Router } from '@angular/router';
import { RouterTestingHarness } from '@angular/router/testing';
import { routes } from './app.routes';
import { HomeComponent } from './home/home';
import { LearnComponent } from './learn/learn';

describe('App routes', () => {
  let harness: RouterTestingHarness;
  let router: Router;

  beforeEach(async () => {
    TestBed.configureTestingModule({
      providers: [provideRouter(routes)],
    });
    harness = await RouterTestingHarness.create();
    router = TestBed.inject(Router);
  });

  it('should load HomeComponent when navigating to /', async () => {
    const component = await harness.navigateByUrl('/');
    expect(component).toBeInstanceOf(HomeComponent);
    expect(router.url).toBe('/');
  });

  it('should load LearnComponent when navigating to /learn', async () => {
    const component = await harness.navigateByUrl('/learn');
    expect(component).toBeInstanceOf(LearnComponent);
    expect(router.url).toBe('/learn');
  });

  it('should define exactly two routes', () => {
    expect(routes.length).toBe(2);
    expect(routes.map((r) => r.path)).toEqual(['', 'learn']);
  });
});

import { TestBed } from '@angular/core/testing';
import { AppComponent } from './app';
import { signal } from '@angular/core';
import { TUI_DARK_MODE } from '@taiga-ui/core';
import { appConfig } from './app.config';

describe('AppComponent', () => {
  beforeEach(async () => {
    await TestBed.configureTestingModule({
      imports: [AppComponent],
      providers: [
        ...appConfig.providers,
        { provide: TUI_DARK_MODE, useValue: signal(false) },
      ],
    }).compileComponents();
  });

  it('should inject ThemeService and expose theme name for tui-root', () => {
    const fixture = TestBed.createComponent(AppComponent);
    fixture.detectChanges();

    const tuiRoot = fixture.nativeElement.querySelector('tui-root');
    expect(tuiRoot).toBeTruthy();
    expect(tuiRoot.getAttribute('tuitheme')).toBe('light');
  });
});

